-- Configuração do Supabase para o site da EJUP. Cole tudo no SQL Editor e clique em Run.

-- 1. Newsletter e pedidos in company
create table if not exists public.leads (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  tipo text not null check (tipo in ('newsletter', 'incompany')),
  email text not null,
  nome text, organizacao text, equipe text, tema text, mensagem text, origem text
);
alter table public.leads enable row level security; -- sem políticas: só o servidor acessa
create unique index if not exists leads_newsletter_email on public.leads (lower(email)) where tipo = 'newsletter';

-- 2. Banco de respostas da Minerva
-- Banco de respostas da Minerva. Edite as linhas pelo Table Editor do Supabase.
create table if not exists public.minerva_respostas (
  id text primary key,
  pergunta text not null,
  variacoes text[] not null default '{}',
  palavras text[] not null default '{}',
  resposta text not null,
  ativo boolean not null default true,
  ordem int not null default 0,
  atualizado_em timestamptz not null default now()
);
alter table public.minerva_respostas enable row level security; -- sem políticas: só o servidor do site lê

insert into public.minerva_respostas (id, pergunta, variacoes, palavras, resposta, ordem) values
  ('saudacao', 'Olá', array['oi', 'bom dia', 'boa tarde', 'boa noite', 'tudo bem', 'ola minerva', 'e ai']::text[], array[]::text[], 'Olá. Sou a Minerva, da EJUP. Posso responder sobre a escola, as formações, o EJUPcast, a Coluna Jurídica e como falar com a equipe.', 10),
  ('minerva', 'O que é a Minerva?', array['quem é você', 'você é uma inteligência artificial', 'como você funciona', 'você é um robô', 'quem é a minerva']::text[], array['minerva', 'voce', 'robo']::text[], 'Sou a Minerva, a assistente institucional da EJUP. Respondo com o conteúdo que a própria escola cadastrou sobre a EJUP, as formações e os canais de contato. Quando não tenho a resposta, indico a equipe.', 20),
  ('ejup', 'O que é a EJUP?', array['o que a ejup faz', 'me fale da ejup', 'quem é a ejup', 'sobre a escola']::text[], array['ejup', 'escola']::text[], 'A EJUP é uma escola de educação jurídica continuada, que oferece formações, uma coluna de análise assinada por especialistas e o EJUPcast, seu podcast institucional. Não é um curso preparatório para concursos nem para o exame da OAB: é formação continuada para quem já exerce ou está prestes a exercer sua profissão.', 30),
  ('publico', 'Para quem é a EJUP?', array['a ejup é para mim', 'quem pode estudar na ejup', 'sou estudante posso fazer', 'é para advogados', 'público da ejup']::text[], array['publico', 'estudante', 'advogado', 'indicada']::text[], 'A EJUP é indicada a quem busca profundidade e visão estratégica: advogados e juristas, professores e pesquisadores, profissionais da interface jurídica e estudantes em fase final. Não é indicada a quem procura atalho formativo, fórmula pronta ou promessa de resultado imediato.', 40),
  ('pilares', 'O que a EJUP ensina?', array['quais são os pilares', 'quais áreas a ejup ensina', 'o que é power skills', 'o que é negócios e inovação', 'base jurídica']::text[], array['pilares', 'ensina', 'areas', 'power', 'skills', 'negocios', 'inovacao']::text[], 'Três pilares. Base jurídica: o núcleo técnico e doutrinário do Direito. Negócios & Inovação: como o Direito opera dentro de mercados, empresas e políticas públicas. Power Skills: negociação, mediação, posicionamento profissional e construção de relacionamento.', 50),
  ('diferencial', 'Como a EJUP é diferente de outros cursos jurídicos?', array['qual o diferencial da ejup', 'por que estudar na ejup', 'o que a ejup tem de diferente']::text[], array['diferente', 'diferencial', 'outros', 'cursos']::text[], 'A oferta comum é organizada por velocidade: conteúdo curto, promessa de resultado rápido, técnica descolada de contexto. A EJUP parte do oposto: trata o tempo de estudo como valor e a profundidade como vantagem competitiva. Não substitui o ensino formal: é seu prolongamento qualificado.', 60),
  ('professores', 'Quem ensina na EJUP?', array['quem são os professores', 'quem são os professores da formação', 'quem dá as aulas', 'corpo docente', 'quem é leonardo pivotto', 'quem é maria helena cortez']::text[], array['professores', 'professor', 'ensina', 'docente', 'aulas', 'leonardo', 'pivotto', 'maria', 'helena', 'cortez']::text[], 'As formações e a coluna são conduzidas por profissionais com notório saber em suas áreas: advogados, professores e especialistas com trajetória reconhecida no exercício e na produção intelectual do Direito. Hoje, entre eles, Leonardo Pivotto, advogado e consultor ambiental, e Maria Helena Cortez, advogada e diretora jurídica. Os perfis completos estão na página Professores.', 70),
  ('formacoes', 'Quais formações a EJUP oferece?', array['quais cursos vocês têm', 'lista de cursos', 'formações disponíveis', 'tem curso de direito ambiental', 'quais são as formações', 'tem formação online', 'o curso é presencial', 'os cursos são online']::text[], array['formacoes', 'formacao', 'cursos', 'oferece', 'disponiveis']::text[], 'Hoje a EJUP oferece: Marco Legal do Licenciamento Ambiental (10 horas, online, com certificado); Formação em Pareceres Técnicos Ambientais (8 horas, online, com certificado); e Marco Legal do Licenciamento Ambiental para equipes (5 horas, presencial, no formato in company). Os detalhes de cada uma estão na página Formações.', 80),
  ('licenciamento', 'Como é a formação Marco Legal do Licenciamento Ambiental?', array['curso de licenciamento ambiental', 'lei geral do licenciamento', 'lei 15.190', 'marco legal']::text[], array['licenciamento', '15190', 'marco', 'lei']::text[], 'A formação Marco Legal do Licenciamento Ambiental trata da nova Lei Geral do Licenciamento Ambiental (Lei 15.190/2025), com foco em aplicação prática e segurança jurídica. São 10 horas em 4 módulos, online, com certificado de conclusão, conduzidas por Leonardo Pivotto com participação de Maria Helena Cortez.', 90),
  ('pareceres', 'Como é a Formação em Pareceres Técnicos Ambientais?', array['curso de pareceres', 'como fazer pareceres', 'parecer técnico', 'formação de pareceres', 'me fala da formação de pareceres']::text[], array['pareceres', 'parecer', 'tecnicos']::text[], 'A Formação em Pareceres Técnicos Ambientais vai da estrutura à argumentação: como produzir pareceres robustos e defensáveis. São 8 horas, online, com certificado. Para receber o programa completo, fale com a equipe da EJUP.', 100),
  ('estudar', 'Como faço para estudar na EJUP?', array['como me inscrevo', 'como faço a matrícula', 'quero me inscrever', 'como comprar um curso', 'como faço para entrar', 'como me matriculo']::text[], array['inscrever', 'inscricao', 'matricula', 'estudar', 'comprar', 'ingresso']::text[], 'Cada formação apresenta conteúdo programático, carga horária e forma de ingresso. A inscrição é feita na própria página da formação, pelo botão de inscrição, e as aulas ficam no Portal do Aluno.', 110),
  ('preco', 'Quanto custa uma formação?', array['qual o valor', 'qual o preço do curso', 'tem desconto', 'posso parcelar', 'formas de pagamento', 'quanto custa o curso', 'quanto custa a formação']::text[], array['preco', 'valor', 'custa', 'quanto', 'desconto', 'parcelar', 'pagamento', 'pagar', 'investimento']::text[], 'Os valores e as condições de pagamento estão na página de cada formação. Para dúvidas sobre pagamento, fale com a equipe pelo WhatsApp 85 9 9271.4050 ou pelo e-mail contato@ejup.com.br.', 120),
  ('certificado', 'A EJUP emite certificado?', array['tem certificado', 'o curso dá certificado', 'quando recebo o certificado']::text[], array['certificado', 'certificacao']::text[], 'Sim. O certificado é emitido quando você finaliza a carga horária do curso.', 130),
  ('incompany', 'A EJUP oferece formações in company?', array['treinamento para empresas', 'curso para minha equipe', 'formação para escritório', 'in company', 'proposta para empresa', 'tem curso para minha empresa', 'curso para empresas']::text[], array['incompany', 'company', 'empresa', 'equipe', 'escritorio', 'treinamento', 'proposta']::text[], 'Sim. Para escritórios, departamentos jurídicos e instituições públicas que desejam treinar suas equipes, a EJUP oferece formações fechadas e personalizadas. Para receber uma proposta, use o formulário da página In company ou fale com a equipe pelo WhatsApp 85 9 9271.4050.', 140),
  ('ejupcast', 'O que é o EJUPcast?', array['vocês têm podcast', 'onde ouvir o podcast', 'episódios do ejupcast']::text[], array['ejupcast', 'podcast', 'episodio', 'episodios']::text[], 'É o podcast institucional da EJUP: conversas longas com profissionais que construíram trajetória no Direito, nos negócios e nas instituições. Está disponível no YouTube e no Spotify. A EJUP é uma escola; o podcast é um de seus meios.', 150),
  ('coluna', 'O que é a Coluna Jurídica?', array['vocês publicam artigos', 'onde leio os artigos', 'blog da ejup']::text[], array['coluna', 'artigos', 'artigo', 'blog']::text[], 'A Coluna Jurídica reúne ensaios, comentários e análises de quem pensa o Direito com profundidade, assinados por especialistas. Os textos estão na página Coluna Jurídica do site.', 160),
  ('newsletter', 'Como recebo a newsletter?', array['quero receber os artigos por email', 'tem newsletter', 'como assinar']::text[], array['newsletter', 'assinar', 'email']::text[], 'A newsletter é semanal, com artigos, reflexões e comentários. Para assinar, deixe seu e-mail no campo de newsletter do site, na Home ou na Coluna Jurídica.', 170),
  ('contato', 'Como falo com a equipe da EJUP?', array['qual o telefone', 'qual o whatsapp', 'qual o email', 'contato', 'falar com alguém', 'atendimento']::text[], array['contato', 'telefone', 'whatsapp', 'email', 'equipe', 'atendimento', 'falar']::text[], 'Você fala com a equipe da EJUP pelo WhatsApp 85 9 9271.4050 ou pelo e-mail contato@ejup.com.br.', 180),
  ('endereco', 'Onde fica a EJUP?', array['qual o endereço', 'onde vocês ficam', 'a ejup é de natal', 'onde fica a escola', 'onde é a sede']::text[], array['endereco', 'onde', 'fica', 'natal', 'localizacao']::text[], 'A EJUP fica na Rua da Saudade, 1028, Lagoa Nova, Natal/RN.', 190),
  ('juridica', 'Você pode me dar uma orientação jurídica?', array['tenho um caso', 'preciso de um advogado', 'me ajuda com um processo', 'isso é legal', 'posso processar']::text[], array['caso', 'processo', 'processar', 'advogado', 'orientacao', 'consulta']::text[], 'Não dou orientação para casos concretos. Para analisar uma situação real, procure um advogado. Aqui eu respondo sobre a EJUP, as formações e os conteúdos da escola.', 200)
on conflict (id) do update set pergunta = excluded.pergunta, variacoes = excluded.variacoes,
  palavras = excluded.palavras, resposta = excluded.resposta, ordem = excluded.ordem, atualizado_em = now();
